def solve(graph, start):
    distance = [-1] * len(graph)
    distance[start] = 0
    queue = [start]
    head = 0
    while head < len(queue):
        current = queue[head]
        head += 1
        for neighbor in graph[current]:
            if distance[neighbor] == -1:
                distance[neighbor] = distance[current] + 1
                queue.append(neighbor)
    return distance

