function solve(values, width) {
  const result = [];
  let total = 0;
  for (let i = 0; i < values.length; i++) {
    total += values[i];
    if (i >= width) total -= values[i - width];
    if (i + 1 >= width) result.push(total / width);
  }
  return result;
}

